 /// The keys a config file may set. `validate_config` rejects any other key.
 const KNOWN_KEYS: [&str; 12] = [
     "timeout", "retries", "proxy", "cache_dir", "log_level", "color",
     "editor", "pager", "theme", "locale", "telemetry", "update_check",
 ];

+/// Returns the `--help` section that lists the config keys, one per line in sorted order.
+pub fn config_keys_help() -> String {
+    assert!(!has_duplicates(&KNOWN_KEYS), "duplicate config key");
+    let mut keys = KNOWN_KEYS.to_vec();
+    keys.sort_unstable();
+    keys.iter().map(|key| format!("  {key}")).collect::<Vec<_>>().join("\n")
+}
+
+fn has_duplicates(keys: &[&str]) -> bool {
+    let mut sorted = keys.to_vec();
+    sorted.sort_unstable();
+    sorted.windows(2).any(|pair| pair[0] == pair[1])
+}
